data.library=data.library||{};
data.libraryPrefs=data.libraryPrefs||[{format:'11',role:'winger',formation:'4-3-3',focus:'scan',weekType:'match'},{format:'9',role:'',formation:'3-2-3',focus:'scan',weekType:'match'}];
let libraryView='path',lessonId=null,category='All',query='';
const lessonById=Object.fromEntries(lessons.map(l=>[l.id,l]));
const libraryStyle=document.createElement('style');libraryStyle.textContent=`
#sections{flex-wrap:nowrap;overflow-x:auto;padding-bottom:4px}#sections button{flex:0 0 auto;white-space:nowrap}#sections button.active{background:#17243c;color:white}.library-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.library-grid .panel{margin:0}.library-grid h3{margin:8px 0}.library-grid p{line-height:1.5}.library-controls{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:14px 0}.library-controls label{display:grid;gap:6px;font-size:13px;font-weight:700}.library-controls select,.library-controls input{width:100%;min-width:0;border:1px solid #cbd4e3;border-radius:10px;padding:11px;background:white}.pitch{position:relative;max-width:420px;aspect-ratio:3/4;background:repeating-linear-gradient(#17694e 0 12.5%,#1a7255 12.5% 25%);border:2px solid #e1f2e5;border-radius:14px;margin:18px auto;overflow:hidden}.pitch:before{content:'';position:absolute;inset:6%;border:1px solid #ffffff75}.pitch:after{content:'';position:absolute;left:6%;right:6%;top:50%;border-top:1px solid #ffffff75}.pitch-center{position:absolute;border:1px solid #ffffff75;width:24%;aspect-ratio:1;border-radius:50%;left:38%;top:41%}.pitch-box{position:absolute;border:1px solid #ffffff75;width:52%;height:15%;left:24%}.pitch-box.top{top:6%}.pitch-box.bottom{bottom:6%}.pitch button{position:absolute;transform:translate(-50%,-50%);padding:0;width:42px;min-height:42px;border-radius:50%;background:#f5f8ff;color:#17243c;border:2px solid white;font-size:12px;z-index:1;box-shadow:0 2px 8px #0003}.pitch button.selected{background:#f2b84b;border-color:white}.pitch-label{position:absolute;top:1%;width:100%;text-align:center;color:white;font-size:10px;letter-spacing:2px}.lesson-copy p,.lesson-copy li{line-height:1.6}.lesson-copy li{margin:8px 0}.lesson-copy .checkline{display:flex;gap:12px;align-items:flex-start;padding:12px 0;border-bottom:1px solid #e5eaf2}.checkline input{width:22px;height:22px;accent-color:#167047;flex-shrink:0}.path-item{display:flex;align-items:center;gap:12px;padding:12px 0;border-top:1px solid #e5eaf2}.path-item button{flex:1;text-align:left}.library-count{font-size:13px;color:#61708a}.phase-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.phase-grid div{padding:14px;background:#f3f5fa;border-radius:12px}.phase-grid p{font-size:14px;line-height:1.5}.lesson-note{width:100%;padding:12px;font:inherit;border:1px solid #cbd4e3;border-radius:10px}.week-card{border-top:4px solid #215adb}.week-card.light{border-top-color:#7441c4}.source-note{font-size:12px;line-height:1.5;color:#61708a}.lesson-hero{background:#17243c;color:white}.lesson-hero p,.lesson-hero small{color:#d3def1}.nextcue{background:#e7f4e9;border-radius:12px;padding:14px}.lib-progress{height:6px;background:#e4eaf1;border-radius:6px;margin:12px 0}.lib-progress span{display:block;height:100%;background:#167047;border-radius:6px}@media(max-width:600px){.library-grid,.phase-grid{grid-template-columns:1fr}.library-controls{grid-template-columns:1fr}.pitch{max-width:360px}.pitch button{width:38px;min-height:38px}.path-item{gap:7px}}
`;document.head.appendChild(libraryStyle);
const libButton=document.createElement('button');libButton.textContent='Learning library';libButton.dataset.libraryNav='library';const weekButton=document.createElement('button');weekButton.textContent='Sessions';weekButton.dataset.libraryNav='week';$('sections').prepend(weekButton,libButton);
const libraryArea=document.createElement('section');libraryArea.id='libraryArea';libraryArea.hidden=true;$('learningArea').after(libraryArea);
function prefs(){return data.libraryPrefs[player]}
function lessonRecord(id){const k=player+'|'+prefs().format+'|'+id;return data.library[k]||(data.library[k]={checks:{},evidence:'',updated:null})}
function countLesson(id){return Object.values(lessonRecord(id).checks).filter(Boolean).length}
function lessonStatus(id){const n=countLesson(id);return n===0?'Not started':n===1?'Exploring':n<4?'Practicing':'Applied · self-reported'}
function selectedPath(){return prefs().role?positionPaths[prefs().role].path:['scan','touch','pass','support','defend','transition']}
function goLesson(id){pause();section='library';lessonId=id;render();$('libraryArea').scrollIntoView({behavior:'smooth',block:'start'})}
function lessonCard(l){const n=countLesson(l.id);return '<article class="panel"><small>'+escapeHTML(l.category)+'</small><h3>'+escapeHTML(l.title)+'</h3><p>'+escapeHTML(l.why)+'</p><div class="lib-progress"><span style="width:'+n*25+'%"></span></div><div class="row between"><span class="library-count">'+lessonStatus(l.id)+'</span><button data-lesson="'+l.id+'">Open lesson →</button></div></article>'}
function libraryControls(){const p=prefs();return '<div class="library-controls"><label>Game format<select id="libFormat"><option value="9" '+(p.format==='9'?'selected':'')+'>9v9</option><option value="11" '+(p.format==='11'?'selected':'')+'>11v11</option></select></label><label>Explore a position<select id="libRole"><option value="">All-player foundations</option>'+Object.entries(positionPaths).map(([id,r])=>'<option value="'+id+'" '+(p.role===id?'selected':'')+'>'+r.name+'</option>').join('')+'</select></label></div>'}
function boardHTML(){const p=prefs(),shape=formations[p.format][p.formation];return '<label>Formation example <select id="libFormation">'+Object.keys(formations[p.format]).map(f=>'<option '+(f===p.formation?'selected':'')+'>'+f+'</option>').join('')+'</select></label><div class="pitch" role="group" aria-label="'+p.format+'v'+p.format+' '+p.formation+' formation. Tap a position to explore its role."><span class="pitch-label">ATTACKING DIRECTION ↑</span><span class="pitch-center"></span><span class="pitch-box top"></span><span class="pitch-box bottom"></span>'+shape.map(([name,x,y,role])=>'<button data-pitch-role="'+role+'" class="'+(role===p.role?'selected':'')+'" style="left:'+x+'%;top:'+y+'%" aria-label="'+name+' — '+positionPaths[role].name+'">'+name+'</button>').join('')+'</div><p class="source-note">'+p.format+' players including the goalkeeper. Formation numbers count outfield players only. Tap a position. These are starting-shape examples, not fixed locations or Galaxy’s confirmed formation. Your coach’s instructions come first.</p>'}
function positionHTML(){const p=prefs(),r=positionPaths[p.role];return '<div class="library-grid"><section class="panel">'+boardHTML()+'</section><section class="panel">'+(r?'<small>POSITION PATHWAY</small><h2>'+r.name+'</h2><p>'+r.mission+'</p><p class="note">'+(p.format==='9'?r.nine:r.eleven)+'</p><button data-library-view="path">See my lesson sequence →</button>':'<h2>Pick a position on the field</h2><p>Explore what the role does with the ball, without it and when possession changes. Choosing a role here is a learning preference, not a team assignment.</p>')+'</section></div>'+(r?'<section class="panel" style="margin-top:16px"><h3>Four moments of the game</h3><div class="phase-grid">'+[['We have the ball',r.have],['They have the ball',r.defend],['We win it',r.win],['We lose it',r.lose]].map(([title,copy])=>'<div><strong>'+title+'</strong><p>'+copy+'</p></div>').join('')+'</div></section>':'')}
function pathwayHTML(){const p=prefs(),r=positionPaths[p.role],path=selectedPath(),next=path.find(id=>countLesson(id)<4)||path[0];return '<section class="panel lesson-hero"><small>'+p.format+'v'+p.format+' · '+(r?r.name:'All-player foundations')+'</small><h2>A clear route through the game.</h2><p>Work on one concept at a time. Use the practice inside your chosen session, not as extra training on top.</p><button class="primary" data-lesson="'+next+'">'+(countLesson(next)?'Continue: ':'Start: ')+lessonById[next].title+'</button></section><section class="panel"><h3>Your suggested sequence</h3><p class="muted">You can open any lesson. Checkoffs track learning steps, not a coach-verified mastery score.</p>'+path.map((id,i)=>'<div class="path-item"><span class="num">'+(i+1)+'</span><button data-lesson="'+id+'">'+lessonById[id].title+'<br><small>'+lessonStatus(id)+'</small></button><span class="pill '+(countLesson(id)===4?'done':'count')+'">'+countLesson(id)+'/4</span></div>').join('')+'</section><section class="panel"><h3>What changes from 9v9 to 11v11?</h3><p>Both use the same foundations: see the game, control the ball, support teammates and protect dangerous space. In 9v9, one player may combine jobs that become more distinct in 11v11. In 11v11, check the extra relationships across midfield and the back line.</p><p>Use the format selector to read the application for each lesson. Learning progress is recorded separately for each format; the technical skill itself carries across.</p><small>League details such as offside, heading, restarts and field dimensions should be confirmed with the team. This library does not set local competition rules.</small></section>'}
function detailHTML(id){const l=lessonById[id],p=prefs(),r=lessonRecord(id);return '<button data-back-library="true">← Back to library</button><section class="panel lesson-hero" style="margin-top:14px"><small>'+l.category+' · '+p.format+'v'+p.format+'</small><h2>'+l.title+'</h2><p>'+l.why+'</p><button data-set-focus="'+id+'">'+(p.focus===id?'✓ Current weekly focus':'Use as this week’s focus')+'</button></section><div class="lesson-copy"><section class="panel"><h3>1. Understand the job</h3><ul>'+l.cues.map(c=>'<li>'+c+'</li>').join('')+'</ul><p><strong>Common mistake:</strong> '+l.mistake+'</p><div class="nextcue"><strong>In '+p.format+'v'+p.format+'</strong><p>'+ (p.format==='9'?l.nine:l.eleven)+'</p></div>'+(l.prereq.length?'<p class="muted">Helpful foundations:</p><div class="row">'+l.prereq.map(k=>'<button data-lesson="'+k+'">'+lessonById[k].title+'</button>').join('')+'</div>':'')+'</section><section class="panel"><h3>2. Watch with a question</h3><p>Look for the cues above. Videos show the skill or principle; the small-space practice below is our adaptation.</p>'+l.video.map(videoHTML).join('')+'</section><section class="panel"><h3>3. Read the game</h3><p>'+l.scenario+'</p><details><summary>Explain your choice, then compare</summary><p>'+l.answer+'</p></details></section><section class="panel"><h3>4. Practice the idea</h3><p class="muted">Choose one option. About 5 minutes including resets and rest. Begin after your normal warm-up, use a clear safe area and stop if tired or uncomfortable.</p><div class="phase-grid"><div><strong>On my own</strong><p>'+l.solo+'</p></div><div><strong>With my brother</strong><p>'+l.duo+'</p></div></div><details><summary>Add decisions when ready</summary><p>'+l.pressure+'</p></details><button class="hold" data-practice="300" data-practice-label="'+escapeHTML(l.title)+'">Start 5-minute practice block</button><p class="source-note">Quality and decisions matter more than filling the timer. Solo work cannot fully reproduce opponents. These blocks replace part of your existing ball session.</p></section><section class="panel"><h3>5. Look for it in a match</h3><p>'+l.evidence+'</p><p>Bring one useful example back. A good decision can count even when the pass or shot did not work.</p>'+[['watch','I watched the demonstration and named the main cue'],['explain','I explained the decision in the scenario'],['practice','I practiced the idea with control'],['match','I noticed or used it in a match and can describe it']].map(([key,label])=>'<label class="checkline"><input type="checkbox" data-lesson-check="'+key+'" '+(r.checks[key]?'checked':'')+'><span>'+label+'</span></label>').join('')+'<label for="lessonEvidence"><p>My example / what I still need help with</p></label><textarea class="lesson-note" id="lessonEvidence" rows="4" maxlength="1500" placeholder="What I saw → what I chose → what happened">'+escapeHTML(r.evidence)+'</textarea><p class="source-note">Saved automatically on this device for '+escapeHTML(data.names[player])+', '+p.format+'v'+p.format+'. Self-reported learning; no remote parent sync.</p></section></div>'}
function renderLibrary(){const p=prefs();let html='<section class="panel"><small>GALAXY LEARNING LIBRARY</small><h2>Learn a skill. Understand a role.</h2><p>16 foundational lessons · 8 position pathways · 9v9 and 11v11</p>'+libraryControls()+'<div class="row tabs">'+[['path','My pathway'],['skills','Browse skills'],['positions','Explore positions']].map(([id,label])=>'<button data-library-view="'+id+'" class="'+(libraryView===id?'active':'')+'">'+label+'</button>').join('')+'</div></section>';if(lessonId)html+=detailHTML(lessonId);else if(libraryView==='positions')html+=positionHTML();else if(libraryView==='skills'){const matches=lessons.filter(l=>(category==='All'||l.category===category)&&(!query||(l.title+' '+l.category+' '+l.why).toLowerCase().includes(query.toLowerCase())));html+='<section class="panel"><div class="library-controls"><label>Find a skill<input id="libSearch" type="search" value="'+escapeHTML(query)+'" placeholder="First touch, defending, passing…"></label><label>Skill family<select id="libCategory">'+['All',...new Set(lessons.map(l=>l.category))].map(c=>'<option '+(c===category?'selected':'')+'>'+c+'</option>').join('')+'</select></label></div><small>'+matches.length+' lessons</small></section><div class="library-grid">'+(matches.length?matches.map(lessonCard).join(''):'<p>No matching lessons. Try another word or choose All.</p>')+'</div>'}else html+=pathwayHTML();html+='<details class="panel"><summary>About the library & sources</summary><p>Lessons are coaching syntheses and family-practice adaptations, supported by the linked FIFA Training Centre, England Football Learning and named demonstration creators. Position examples are starting points to discuss with your coach.</p><p>The lessons and notes are contained here. Embedded or linked videos need internet access and remain on their creators’ platforms; this is not an offline video collection. Some creators require an account or block embedding.</p><p>This foundation library does not yet include every specialist skill, set-piece scheme or goalkeeper saving technique.</p><a href="https://learn.englandfootball.com/articles-and-resources/coaching/resources/2022/What-are-the-principles-of-football" target="_blank" rel="noopener">FA: Principles of football</a></details>';$('libraryArea').innerHTML=html;}
function renderWeek(){const focus=lessonById[prefs().focus];$('libraryArea').innerHTML='<section class="panel"><h2>Choose a session</h2><p>Fit training around your recovery, team practices and matches. There are no assigned weekdays.</p><div class="row"><button data-week-action="A">Control & stability</button><button data-week-action="B">Balance & body control</button><button data-week-action="ball">Ball training</button><button data-lesson="'+focus.id+'">Learn my focus</button></div><p>Keep lifting on separate days. Choose rest or learning when fatigued or close to a match.</p></section>';}
const priorLearnRender=learnRender;learnRender=function(){if(section==='library'||section==='week'){$('learningArea').hidden=true;$('strengthArea').hidden=true;$('historyArea').hidden=true;$('libraryArea').hidden=false;document.querySelectorAll('#sections button').forEach(b=>b.classList.remove('active'));(section==='library'?libButton:weekButton).classList.add('active');section==='library'?renderLibrary():renderWeek();return}$('libraryArea').hidden=true;libButton.classList.remove('active');weekButton.classList.remove('active');priorLearnRender();if(section==='soccer'){const l=lessonById[prefs().focus];$('learningArea').insertAdjacentHTML('afterbegin','<section class="panel"><h3>Library focus: '+l.title+'</h3><p>Use this lesson’s five-minute drill instead of the weekly theme block below when using a focus session.</p><button data-lesson="'+l.id+'">Open my focus</button></section>')}if(section==='strength'){$('cards').insertAdjacentHTML('beforebegin','<p class="note scheduleReminder" id="scheduleReminder">Choose lifting only when recovered and not close to a match. Keep strength sessions on separate days; skip extra lifting during congested tournament periods.</p>');document.querySelectorAll('.scheduleReminder').forEach((e,i)=>{if(i>0)e.remove()})}};
const priorHistory=historyRender;historyRender=function(){priorHistory();const rows=Object.entries(data.library).filter(([k,r])=>Number(k.split('|')[0])===player&&(Object.values(r.checks).some(Boolean)||r.evidence));$('historyArea').insertAdjacentHTML('beforeend','<section class="panel"><h3>Library learning</h3><p class="muted">Separate progress for each format. No automatic mastery certification.</p>'+(rows.length?rows.map(([k,r])=>{const [,format,id]=k.split('|');return '<p><strong>'+escapeHTML(lessonById[id]?.title||id)+'</strong> · '+format+'v'+format+' · '+Object.values(r.checks).filter(Boolean).length+'/4 steps<br>'+escapeHTML(r.evidence||'No match example recorded yet.')+'</p>'}).join(''):'<p>No library steps recorded yet.</p>')+'</section>')};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.libraryNav){pause();section=b.dataset.libraryNav;lessonId=null;render()}if(b.dataset.lesson)goLesson(b.dataset.lesson);if(b.dataset.libraryView){lessonId=null;libraryView=b.dataset.libraryView;renderLibrary()}if(b.dataset.backLibrary){lessonId=null;renderLibrary()}if(b.dataset.pitchRole){prefs().role=b.dataset.pitchRole;persist();renderLibrary()}if(b.dataset.setFocus){prefs().focus=b.dataset.setFocus;persist();renderLibrary()}if(b.dataset.weekAction){pause();const a=b.dataset.weekAction;if(a==='A'||a==='B'){day=a;section='strength'}else if(a==='ball'){section='soccer';ballDay='B'}else section='watch';render();}});
$('libraryArea').addEventListener('change',e=>{const t=e.target;if(t.id==='libFormat'){pause();prefs().format=t.value;prefs().formation=Object.keys(formations[t.value])[0];persist();renderLibrary()}if(t.id==='libRole'){prefs().role=t.value;lessonId=null;persist();renderLibrary()}if(t.id==='libFormation'){prefs().formation=t.value;persist();renderLibrary()}if(t.id==='libCategory'){category=t.value;renderLibrary()}if(t.id==='weekType'){prefs().weekType=t.value;persist();renderWeek()}if(t.dataset.lessonCheck){const r=lessonRecord(lessonId);r.checks[t.dataset.lessonCheck]=t.checked;r.updated=new Date().toISOString();persist();}});
$('libraryArea').addEventListener('input',e=>{if(e.target.id==='lessonEvidence'){const r=lessonRecord(lessonId);r.evidence=e.target.value;r.updated=new Date().toISOString();persist()}if(e.target.id==='libSearch'){const pos=e.target.selectionStart;query=e.target.value;renderLibrary();const search=$('libSearch');search.focus();if(search.type!=='search')search.setSelectionRange(pos,pos)}});
$('export').onclick=()=>{const selected=obj=>Object.fromEntries(Object.entries(obj||{}).filter(([k])=>k.startsWith(player+'|')));const out={player:data.names[player],exported:new Date().toISOString(),scope:'This device only. Self-reported; no actual rep, timer or watch-time tracking.',preferences:prefs(),strength:selected(data.records),soccerAndLearning:selected(data.learning),demonstrations:selected(data.demoChecks),library:selected(data.library)};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:'application/json'}));a.download='galaxy-'+data.names[player].replace(/[^a-z0-9]/gi,'-')+'-training-log.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
section='week';persist();render();
